import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 인수인계 대상 문서 범위는 진행중·완료 문서를 모두 포함한다 (결정). 상태 제한 없음.
// 가정: 인계자·인수자 중 하나 이상이 임직원 또는 부서로 지정되어야 한다.

function optId(v: unknown, name: string): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v === 'number' && Number.isInteger(v) && v > 0) {
    return v;
  }
  if (typeof v === 'string' && /^[0-9]+$/.test(v) && Number(v) > 0) {
    return Number(v);
  }
  throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값은 양의 정수여야 합니다.');
}

@Controller('api/v1')
export class FnSfr03102Controller {
  @Post('/approval-documents/handover')
  @HttpCode(200)
  async handoverApprovalDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const reason = typeof data['reason'] === 'string' ? data['reason'].trim() : '';
    if (reason === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '인수인계 사유를 입력해 주세요.');
    }
    const fromEmp = optId(data['fromEmployeeId'], '인계자 임직원 ID');
    const toEmp = optId(data['toEmployeeId'], '인수자 임직원 ID');
    const fromDept = optId(data['fromDepartmentId'], '인계 부서 ID');
    const toDept = optId(data['toDepartmentId'], '인수 부서 ID');
    if (fromEmp === null && fromDept === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인계자 또는 인계 부서를 선택해 주세요.');
    }
    if (toEmp === null && toDept === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인수자 또는 인수 부서를 선택해 주세요.');
    }
    return transaction(async (db) => {
      if (fromEmp !== null) {
        const rows = await db.query('SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)', { id: fromEmp });
        if (rows.length === 0) {
          throw new ApiError(404, 'HANDOVER_SOURCE_NOT_FOUND', '인계 대상 임직원이 존재하지 않습니다.');
        }
      }
      if (fromDept !== null) {
        const rows = await db.query('SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)', { id: fromDept });
        if (rows.length === 0) {
          throw new ApiError(404, 'HANDOVER_SOURCE_NOT_FOUND', '인계 대상 부서가 존재하지 않습니다.');
        }
      }
      let toEmpDept: number | null = null;
      if (toEmp !== null) {
        if (toEmp === fromEmp) {
          throw new ApiError(422, 'HANDOVER_TARGET_INVALID', '인계자와 인수자가 동일합니다.');
        }
        const rows = await db.query('SELECT department_id AS "departmentId", employment_status AS "status" FROM employee WHERE employee_id = CAST(:id AS bigint)', { id: toEmp });
        if (rows.length === 0 || rows[0]['status'] !== '재직') {
          throw new ApiError(422, 'HANDOVER_TARGET_INVALID', '인수자가 유효하지 않습니다.');
        }
        toEmpDept = rows[0]['departmentId'] === null ? null : Number(rows[0]['departmentId']);
      }
      if (toDept !== null) {
        if (toDept === fromDept) {
          throw new ApiError(422, 'HANDOVER_TARGET_INVALID', '인계 부서와 인수 부서가 동일합니다.');
        }
        const rows = await db.query('SELECT use_yn AS "useYn" FROM department WHERE department_id = CAST(:id AS bigint)', { id: toDept });
        if (rows.length === 0 || rows[0]['useYn'] !== '사용') {
          throw new ApiError(422, 'HANDOVER_TARGET_INVALID', '인수 부서가 유효하지 않습니다.');
        }
      }
      const docs = await db.query(
        'SELECT approval_document_id AS "approvalDocumentId", drafter_id AS "drafterId", drafter_department_id AS "drafterDepartmentId" FROM approval_document WHERE (CAST(:fromEmp AS bigint) IS NULL OR drafter_id = CAST(:fromEmp AS bigint)) AND (CAST(:fromDept AS bigint) IS NULL OR drafter_department_id = CAST(:fromDept AS bigint)) ORDER BY approval_document_id FOR UPDATE',
        { fromEmp, fromDept },
      );
      let successCount = 0;
      let firstId: number | null = null;
      const failedDocuments: { approvalDocumentId: number; reason: string }[] = [];
      for (const doc of docs) {
        const docId = Number(doc['approvalDocumentId']);
        const oldDrafter = Number(doc['drafterId']);
        const oldDept = Number(doc['drafterDepartmentId']);
        const newDrafter = toEmp !== null ? toEmp : oldDrafter;
        const newDept = toDept !== null ? toDept : toEmpDept !== null ? toEmpDept : oldDept;
        const changed = await db.execute(
          'UPDATE approval_document SET drafter_id = CAST(:newDrafter AS bigint), drafter_department_id = CAST(:newDept AS bigint), updated_at = now() WHERE approval_document_id = CAST(:docId AS bigint) AND drafter_id = CAST(:oldDrafter AS bigint) AND drafter_department_id = CAST(:oldDept AS bigint)',
          { newDrafter, newDept, docId, oldDrafter, oldDept },
        );
        if (changed === 0) {
          failedDocuments.push({ approvalDocumentId: docId, reason: '문서가 이미 변경되어 처리하지 못했습니다.' });
          continue;
        }
        if (toEmp !== null && fromEmp !== null) {
          await db.execute(
            'UPDATE approval_line SET approver_id = CAST(:toEmp AS bigint), updated_at = now() WHERE approval_document_id = CAST(:docId AS bigint) AND approver_id = CAST(:fromEmp AS bigint) AND action_type IS NULL',
            { toEmp, fromEmp, docId },
          );
        }
        const before = JSON.stringify({ drafterId: oldDrafter, drafterDepartmentId: oldDept });
        const after = JSON.stringify({ drafterId: newDrafter, drafterDepartmentId: newDept, reason });
        await db.execute(
          'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) VALUES (\'approval_document\', CAST(:docId AS bigint), \'수정\', now(), CAST(:userId AS bigint), :before, :after, now(), now())',
          { docId, userId: user.id, before, after },
        );
        successCount += 1;
        if (firstId === null) {
          firstId = docId;
        }
      }
      if (successCount > 0) {
        let receivers: number[] = [];
        if (toEmp !== null) {
          receivers = [toEmp];
        } else if (toDept !== null) {
          const emps = await db.query('SELECT employee_id AS "employeeId" FROM employee WHERE department_id = CAST(:dept AS bigint) AND employment_status = \'재직\'', { dept: toDept });
          receivers = emps.map((e) => Number(e['employeeId']));
        }
        for (const receiver of receivers) {
          await db.execute(
            'INSERT INTO notification (employee_id, notification_type, event_type, title, summary, detail, target_type, target_id, read_yn, occurred_at, created_at, updated_at) VALUES (CAST(:receiver AS bigint), \'ALERT\', \'APPROVAL_HANDOVER\', \'결재문서 인수인계\', :summary, :detail, \'DOCUMENT\', CAST(:targetId AS bigint), false, now(), now(), now())',
            { receiver, summary: '결재문서 ' + successCount + '건이 인수인계되었습니다.', detail: reason, targetId: firstId },
          );
        }
      }
      return { successCount, failedDocuments };
    });
  }
}

