import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Filters, Form, LookupSelect, Pager, Pairs, RefName, Select, TextInput, Tiles, call, useData } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 10;

export default function FnSfr03102Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [drafterId, setDrafterId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState('');
  const [fromEmp, setFromEmp] = useState<number | string>('');
  const [toEmp, setToEmp] = useState<number | string>('');
  const [fromDept, setFromDept] = useState<number | string>('');
  const [toDept, setToDept] = useState<number | string>('');
  const [result, setResult] = useState<Row | undefined>(undefined);

  const list = useData<Page>(
    () => call<Page>('GET', '/approval-documents', role, undefined, { page, size: SIZE, drafterId, approvalStatus: status }),
    [page, drafterId, status, role],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const failed = result && Array.isArray(result['failedDocuments']) ? (result['failedDocuments'] as Row[]) : [];

  function resetForm() {
    setReason('');
    setFromEmp('');
    setToEmp('');
    setFromDept('');
    setToDept('');
  }

  async function submit() {
    if (reason.trim() === '') {
      throw new Error('인수인계 사유를 선택해 주세요.');
    }
    if (fromEmp === '' && fromDept === '') {
      throw new Error('인계자 또는 인계 부서를 선택해 주세요.');
    }
    if (toEmp === '' && toDept === '') {
      throw new Error('인수자 또는 인수 부서를 선택해 주세요.');
    }
    const res = await call('POST', '/approval-documents/handover', role, {
      reason,
      fromEmployeeId: fromEmp === '' ? undefined : fromEmp,
      toEmployeeId: toEmp === '' ? undefined : toEmp,
      fromDepartmentId: fromDept === '' ? undefined : fromDept,
      toDepartmentId: toDept === '' ? undefined : toDept,
    });
    setResult(res);
    notify('인수인계를 처리했습니다.');
    setOpen(false);
    resetForm();
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>인수인계 결과</h2>
        <Tiles
          items={[
            ['조회 문서 건수', total],
            ['인수인계 성공', result ? String(result['successCount']) : '-'],
            ['인수인계 실패', result ? failed.length : '-'],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>인수인계 대상 문서</h2>
        <Filters
          onSearch={() => setPage(0)}
          onReset={() => {
            setDrafterId('');
            setStatus('');
            setPage(0);
          }}
        >
          <Field label="기안자">
            <LookupSelect table="employee" role={role} value={drafterId} onChange={(v) => { setDrafterId(v); setPage(0); }} />
          </Field>
          <Field label="결재 진행 상태">
            <Select
              value={status}
              onChange={(v) => { setStatus(v); setPage(0); }}
              options={['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'].map((s): [string, string] => [s, s])}
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => setOpen(true)}>인수인계</button>
        </Band>
        <DataTable
          rows={rows}
          empty="조회된 결재문서가 없습니다."
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '문서 제목' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
            { key: 'drafterId', label: '기안자', render: (r) => <RefName table="employee" role={role} value={r['drafterId']} /> },
            { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r['submittedAt']} time /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {failed.length > 0 && (
        <section className="box span-12">
          <h2>실패 문서</h2>
          <DataTable
            rows={failed}
            columns={[
              { key: 'approvalDocumentId', label: '결재문서 ID' },
              { key: 'reason', label: '실패 사유' },
            ]}
          />
        </section>
      )}
      {open && (
        <Drawer title="전자결재 문서 인수인계" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="인수인계 실행" note="진행중·완료 문서를 모두 인수자에게 넘깁니다. 위 목록에서 대상 범위를 먼저 확인해 주세요.">
            <Field label="인수인계 사유(입사·퇴사·부서 통폐합 등)" required wide>
              <TextInput value={reason} onChange={setReason} placeholder="예: 퇴사" />
            </Field>
            <Field label="인계자 임직원 ID">
              <LookupSelect table="employee" role={role} value={fromEmp} onChange={setFromEmp} />
            </Field>
            <Field label="인수자 임직원 ID">
              <LookupSelect table="employee" role={role} value={toEmp} onChange={setToEmp} />
            </Field>
            <Field label="인계 부서 ID">
              <LookupSelect table="department" role={role} value={fromDept} onChange={setFromDept} />
            </Field>
            <Field label="인수 부서 ID">
              <LookupSelect table="department" role={role} value={toDept} onChange={setToDept} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
